// src/types/ai.ts
// Shared types for the AI Learning Module. Content is generated by the backend
// (/api/ai) from the text of the selected document.

export type Difficulty = 'easy' | 'medium' | 'hard';

export type ChatMessage = {
    id: string;
    role: 'user' | 'ai';
    text: string;
    timestamp: string; // ISO date
};

export type FlashcardData = {
    id: string;
    front: string;
    back: string;
    difficulty: Difficulty;
    bookmarked: boolean;
};

export type QuizQuestionType = 'mcq' | 'truefalse' | 'short';

export type QuizQuestion = {
    id: string;
    type: QuizQuestionType;
    difficulty: Difficulty;
    question: string;
    options?: string[]; // mcq: 4 options, truefalse: ['True', 'False']
    correctAnswer: string;
    explanation: string;
};

export type SummarySection = {
    id: string;
    title: string;
    icon: string; // MaterialCommunityIcons name
    points: string[];
};

export type FormulaData = {
    id: string;
    title: string;
    formula: string;
    note: string;
};

export type VivaQuestion = {
    id: string;
    question: string;
    answer: string;
    difficulty: Difficulty;
    bookmarked: boolean;
};

// Route params for the AI Learning Module stack.
export type AIStackParamList = {
    AIHome: undefined;
    Chat: undefined;
    Summary: undefined;
    Flashcards: undefined;
    Quiz: undefined;
    QuizResult: {
        correct: number;
        total: number;
        timeSeconds: number;
        answers: Record<string, string | null>;
        questions: QuizQuestion[];
    };
    Viva: undefined;
};
